#!/usr/bin/env python3
"""Глава «США», пачка 5: акт «Реформы и экспансия», 1825–1848, 9 уровней.

    python3 tools/batches/usa_5.py [repo_root]
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from usa_common import (char, scene, actor, setf, remf, addr, rule, flag, nflag, texts, level, bait, run,
                        PARLEY, BATTLE, ACT5)

def C(id, name, emoji, tags=None):
    return char(id, name, tags or [id], emoji)

CH, SC, RU, LV, TX = [], [], [], [], {}

def L(id, order, mood, cover, panels, scenes, chars, flags, goal, solution, acc, title, gtext, hint, intro, fact, source):
    LV.append(level(id, order, ACT5, mood, cover, panels, scenes, chars, flags, [], goal, solution, acc))
    TX.update(texts(id, title, gtext, hint, intro, fact, source))

def S(id, name, slots, emoji, action, icon, roles, donor):
    SC.append(scene(id, name, [f"sig_{id}"], slots, emoji, action, icon, roles, donor))

def Rl(id, comment, actors, effects):
    RU.append(rule(f"{id}_sig", comment, f"sig_{id}", actors, effects))

